fn linked_list_push() {
    static REG1: Registration = Registration::new(&CS1);
    static REG2: Registration = Registration::new(&CS2);

    let linked_list = LinkedList::new();

    linked_list.push(&REG1);
    linked_list.push(&REG2);

    let mut i = 0;

    linked_list.for_each(|reg| {
        if i == 0 {
            assert!(
                ptr::eq(reg, &REG2),
                "Registration pointers need to match REG2"
            );
        } else {
            assert!(
                ptr::eq(reg, &REG1),
                "Registration pointers need to match REG1"
            );
        }

        i += 1;
    });
}

pub fn with_default<T>(dispatcher: &Dispatch, f: impl FnOnce() -> T) -> T {
    // When this guard is dropped, the default dispatcher will be reset to the
    // prior default. Using this (rather than simply resetting after calling
    // `f`) ensures that we always reset to the prior dispatcher even if `f`
    // panics.
    let _guard = set_default(dispatcher);
    f()
}

